CREATE OR REPLACE FUNCTION public.nurse_visible_assessments() RETURNS TABLE(id uuid,assessment_type text,due_date date,status text,scheduled_date date,scheduled_time time without time zone,notes text,client_name text,form_618_expiration_date date,is_mine boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT a.id,a.assessment_type,a.due_date,a.status,a.scheduled_date,a.scheduled_time,a.notes,c.first_name||' '||c.last_name,CASE WHEN a.assessment_type='Nurse Visit' THEN c.nurse_visit_due_date ELSE c.form_618_expiration_date END,a.assigned_nurse_id=public.current_nurse_id() FROM public.nurse_assessments a JOIN public.clients c ON c.id=a.client_id WHERE c.status<>'test' AND public.has_role(auth.uid(),'nurse'::app_role) AND public.current_nurse_id() IS NOT NULL AND (a.assigned_nurse_id=public.current_nurse_id() OR (a.assigned_nurse_id IS NULL AND a.status='Pending')) ORDER BY a.due_date $$;
CREATE OR REPLACE FUNCTION public.nurse_assessment_detail(p_assessment_id uuid) RETURNS TABLE(id uuid,assessment_type text,due_date date,status text,scheduled_date date,scheduled_time time without time zone,notes text,client_name text,form_618_expiration_date date,is_mine boolean,claimed_by_name text,rescheduled_at timestamp with time zone,reschedule_count integer,previous_scheduled_date date,previous_scheduled_time time without time zone) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT a.id,a.assessment_type,a.due_date,a.status,a.scheduled_date,a.scheduled_time,a.notes,c.first_name||' '||c.last_name,CASE WHEN a.assessment_type='Nurse Visit' THEN c.nurse_visit_due_date ELSE c.form_618_expiration_date END,a.assigned_nurse_id IS NOT NULL AND a.assigned_nurse_id=public.current_nurse_id(),n.first_name||' '||n.last_name,a.rescheduled_at,a.reschedule_count,a.previous_scheduled_date,a.previous_scheduled_time FROM public.nurse_assessments a JOIN public.clients c ON c.id=a.client_id LEFT JOIN public.nurses n ON n.id=a.assigned_nurse_id WHERE a.id=p_assessment_id AND c.status<>'test' AND (public.has_role(auth.uid(),'admin'::app_role) OR (public.has_role(auth.uid(),'nurse'::app_role) AND public.current_nurse_id() IS NOT NULL AND (a.assigned_nurse_id=public.current_nurse_id() OR (a.assigned_nurse_id IS NULL AND a.status='Pending')))) $$;